# AUTO-GENERATED by Claude Code
# Purpose: `ds ui` commands for delulu-smash (the services/ui Reflex app, kept running by the
#          delulu-smash.service systemd user service on Omarchy, a Task Scheduler task on
#          Windows: ds/cli/ui_service.py): the one place that knows how the app runs. The
#          window (SUPER+SHIFT+J / Ctrl+Alt+J) is .os/scripts/keybindings/delulu-smash.py,
#          which calls `status` and `restart` here.
#
# Example CLI Commands:
#   1. The server in the foreground (what the service runs):  ds ui run
#   2. Restart, eg after changing dependencies:              ds ui restart
#   3. Is it up?                                              ds ui status
#   4. The background server's output:                       ds ui logs -f
#   5. Windows, once per machine: task, icon, Ctrl+Alt+J:    ds ui install
#   6. Update the bundled Nerd Font to the latest release:   ds ui fonts
# ---------------------------------------------------------------------------
from __future__ import annotations

import os
import time
import urllib.request
from http import HTTPStatus
from pathlib import Path
from typing import Annotated

import typer
from ds.cli.ui_service import APP_NAME, is_windows, serve, service
from ds.util.const import REPO_DIR

__all__ = ["ui_app"]


ui_app = typer.Typer(help="Run delulu-smash (the services/ui Reflex app)")

APP_DIR = REPO_DIR / "services" / "ui"
FRONTEND_URL = "http://localhost:3000"
BACKEND_PING = "http://127.0.0.1:8000/ping"
# A cold `reflex run` (frontend build + dev server) takes about a minute.
APP_START_TIMEOUT_S = 150


def _up(url: str) -> bool:
    try:
        with urllib.request.urlopen(url, timeout=2) as response:  # noqa: S310  # fixed localhost URLs
            return response.status < HTTPStatus.INTERNAL_SERVER_ERROR
    except OSError:
        return False


def ready() -> bool:
    """Both halves of the Reflex app answer: the page and the backend it talks to."""
    return _up(FRONTEND_URL) and _up(BACKEND_PING)


@ui_app.command("run")
def run(
    log: Annotated[Path | None, typer.Option(help="Write the output to this file (the Windows task)")] = None,
) -> None:
    """Run the Reflex dev server in the foreground (what the background service runs)

    Stop the service first to run it by hand: both use ports 3000 and 8000.
    """
    cmd = ["uv", "run", "reflex", "run"]
    if is_windows() or log:
        # Windows' exec would end this process, which the task and `ds ui restart` track
        raise typer.Exit(serve(cmd, APP_DIR, log))
    os.chdir(APP_DIR)
    os.execvp(cmd[0], cmd)  # noqa: S606  # fixed command, uv from PATH


@ui_app.command("restart")
def restart() -> None:
    """Restart delulu-smash (its service; starts it when stopped) and wait until it answers

    Its server reads stored keys once at start; `ds settings sync` runs this itself.
    """
    svc = service()
    svc.restart()
    typer.echo(f"Waiting for {APP_NAME} to answer (up to about a minute)...")
    deadline = time.monotonic() + APP_START_TIMEOUT_S
    while not ready():
        if time.monotonic() > deadline:
            typer.echo(f"{APP_NAME} didn't come up. Logs: {svc.logs_hint}", err=True)
            raise typer.Exit(1)
        time.sleep(1)
    typer.echo(f"{APP_NAME} is up: {FRONTEND_URL}")


@ui_app.command("status")
def status() -> None:
    """Say whether delulu-smash is answering (exit code 1 when it isn't)"""
    up = ready()
    typer.echo("up" if up else "down")
    raise typer.Exit(0 if up else 1)


@ui_app.command("logs")
def logs(
    lines: Annotated[int, typer.Option("--lines", "-n", help="How many of the last lines")] = 50,
    follow: Annotated[bool, typer.Option("--follow", "-f", help="Keep printing new lines")] = False,
) -> None:
    """Show the background server's output (journalctl on Omarchy, its log file on Windows)"""
    service().logs(lines=lines, follow=follow)


@ui_app.command("install")
def install() -> None:
    """Windows: start delulu-smash at logon, plus a desktop and Start Menu icon (Ctrl+Alt+J)

    Once per machine; no admin needed. On Omarchy, `os sync` sets this up instead.
    """
    service().install()
    restart()


@ui_app.command("uninstall")
def uninstall() -> None:
    """Windows: stop delulu-smash and remove what `ds ui install` created"""
    service().uninstall()


@ui_app.command("fonts")
def fonts(
    version: Annotated[str | None, typer.Option(help="A Nerd Fonts release tag, eg v3.4.0 (default: latest)")] = None,
) -> None:
    """Update the bundled JetBrainsMono Nerd Font (assets/nerd_fonts) from GitHub"""
    from ds.cli.ui_fonts import update_fonts  # here: fontTools is a dev dependency

    update_fonts(version)
